+// reasonSet accumulates violation reasons in first-seen order while rejecting
+// duplicates. Reason strings quote identifiers lifted straight out of the
+// query, so the number of *distinct* reasons is bounded only by the query
+// length, and comparing every new reason against every reason already collected
+// is quadratic in that count. validateSQL hands an authenticated principal up
+// to 1<<20 bytes with no database privilege and no approval, which pinned a
+// core for 13 seconds per request on both dialects.
+//
+// The slice is the only source of order; the map answers membership and nothing
+// else. Reasons below the threshold keep the original linear scan, which covers
+// every ordinary query, so the map is never allocated on the common path.
+type reasonSet struct {
+	values []string
+	index  map[string]struct{}
+}
+
+const reasonSetIndexThreshold = 8
+
+// newReasonSet continues accumulating onto an existing reason list, preserving
+// its order and treating its entries as already seen.
+func newReasonSet(values []string) reasonSet {
+	set := reasonSet{values: values}
+	if len(values) >= reasonSetIndexThreshold {
+		set.buildIndex()
+	}
+	return set
+}
+
+func (s *reasonSet) buildIndex() {
+	s.index = make(map[string]struct{}, len(s.values)*2)
+	for _, value := range s.values {
+		s.index[value] = struct{}{}
+	}
+}
+
+func (s *reasonSet) add(value string) {
+	if s.index != nil {
+		if _, seen := s.index[value]; seen {
+			return
+		}
+	} else {
+		for _, current := range s.values {
+			if current == value {
+				return
+			}
+		}
+		if len(s.values) >= reasonSetIndexThreshold {
+			s.buildIndex()
+		}
+	}
+	s.values = append(s.values, value)
+	if s.index != nil {
+		s.index[value] = struct{}{}
+	}
+}
+
+func (s *reasonSet) list() []string {
+	return s.values
+}
