@@ -636,6 +636,116 @@ func TestAnalyzeDialectScalesLinearlyOverAliasedPostgresCalls(t *testing.T) {
 	}
 }

+// The reasons a blocked statement carries quote identifiers lifted out of the
+// query, so their cardinality is bounded only by the query length. Deduplicating
+// each new reason against every reason already collected is quadratic in the
+// number of *distinct* reasons, and the three cases below are the reason sites
+// that a caller can drive to that cardinality: PostgreSQL function names, Oracle
+// function names, and PostgreSQL cast target types. validateSQL hands an
+// authenticated principal up to 1<<20 bytes with no database privilege at all.
+const distinctReasonTerms = 64000
+
+func TestAnalyzeDialectScalesLinearlyOverDistinctPostgresFunctionReasons(t *testing.T) {
+	var builder strings.Builder
+	builder.WriteString("SELECT ")
+	for index := 0; index < distinctReasonTerms; index++ {
+		if index > 0 {
+			builder.WriteString(", ")
+		}
+		fmt.Fprintf(&builder, "f%d(x)", index)
+	}
+	builder.WriteString(" FROM public.events")
+	query := builder.String()
+
+	start := time.Now()
+	analysis := AnalyzeDialect(query, "postgres")
+	elapsed := time.Since(start)
+
+	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
+		t.Fatalf("distinct stored function calls were accepted: ReadOnly=%t Risk=%s", analysis.ReadOnly, analysis.Risk)
+	}
+	if elapsed > time.Second {
+		t.Fatalf("AnalyzeDialect took %s for a %d byte postgres query producing %d distinct reasons; reason accumulation is comparing each new reason against every reason already collected", elapsed, len(query), distinctReasonTerms)
+	}
+}
+
+func TestAnalyzeDialectScalesLinearlyOverDistinctOracleFunctionReasons(t *testing.T) {
+	var builder strings.Builder
+	builder.WriteString("SELECT ")
+	for index := 0; index < distinctReasonTerms; index++ {
+		if index > 0 {
+			builder.WriteString(", ")
+		}
+		fmt.Fprintf(&builder, "f%d(x)", index)
+	}
+	builder.WriteString(" FROM reporting.sales")
+	query := builder.String()
+
+	start := time.Now()
+	analysis := AnalyzeDialect(query, "oracle")
+	elapsed := time.Since(start)
+
+	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
+		t.Fatalf("distinct stored function calls were accepted: ReadOnly=%t Risk=%s", analysis.ReadOnly, analysis.Risk)
+	}
+	if elapsed > time.Second {
+		t.Fatalf("AnalyzeDialect took %s for a %d byte oracle query producing %d distinct reasons; reason accumulation is comparing each new reason against every reason already collected", elapsed, len(query), distinctReasonTerms)
+	}
+}
+
+func TestAnalyzeDialectScalesLinearlyOverDistinctPostgresCastReasons(t *testing.T) {
+	var builder strings.Builder
+	builder.WriteString("SELECT ")
+	for index := 0; index < distinctReasonTerms; index++ {
+		if index > 0 {
+			builder.WriteString(", ")
+		}
+		fmt.Fprintf(&builder, "x::t%d", index)
+	}
+	builder.WriteString(" FROM public.events")
+	query := builder.String()
+
+	start := time.Now()
+	analysis := AnalyzeDialect(query, "postgres")
+	elapsed := time.Since(start)
+
+	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
+		t.Fatalf("distinct user-defined cast types were accepted: ReadOnly=%t Risk=%s", analysis.ReadOnly, analysis.Risk)
+	}
+	if elapsed > time.Second {
+		t.Fatalf("AnalyzeDialect took %s for a %d byte postgres query producing %d distinct reasons; reason accumulation is comparing each new reason against every reason already collected", elapsed, len(query), distinctReasonTerms)
+	}
+}
+
+// Order and deduplication of the reason list are the observable contract the
+// dialect gates and the merge below AnalyzeDialect share: the base statement
+// reasons come first in scan order, the dialect reasons follow in the order the
+// gate found them, and nothing repeats. This pins the behaviour that the
+// membership index must not change.
+func TestAnalyzeDialectDeduplicatesAndOrdersViolationReasons(t *testing.T) {
+	t.Parallel()
+	analysis := AnalyzeDialect(`SELECT pg_sleep(1), side_effect_fn(x), pg_sleep(2), side_effect_fn(y), other_fn(z) FROM public.events WHERE x COLLATE "C" > 'a' AND y TABLESAMPLE`, "postgres")
+	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
+		t.Fatalf("statement was accepted: %#v", analysis)
+	}
+	want := []string{
+		"관리자 확인이 필요한 함수 PG_SLEEP가 포함되어 있습니다.",
+		"PostgreSQL의 명시적 COLLATE 절은 허용되지 않습니다.",
+		"PostgreSQL TABLESAMPLE access method 호출은 허용되지 않습니다.",
+		"PostgreSQL SELECT의 비허용 함수 호출 pg_sleep()이 포함되어 있습니다.",
+		"PostgreSQL SELECT의 비허용 함수 호출 side_effect_fn()이 포함되어 있습니다.",
+		"PostgreSQL SELECT의 비허용 함수 호출 other_fn()이 포함되어 있습니다.",
+	}
+	if len(analysis.Reasons) != len(want) {
+		t.Fatalf("reasons = %#v, want %d entries", analysis.Reasons, len(want))
+	}
+	for index, reason := range want {
+		if analysis.Reasons[index] != reason {
+			t.Fatalf("reasons[%d] = %q, want %q (full list %#v)", index, analysis.Reasons[index], reason, analysis.Reasons)
+		}
+	}
+}
+
 func TestAnalyzeDialectRejectsOracleExplainPlan(t *testing.T) {
 	t.Parallel()
 	analysis := AnalyzeDialect(`EXPLAIN PLAN FOR SELECT * FROM reporting.sales`, "oracle")

