name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  test:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:17-alpine
        env:
          POSTGRES_USER: qurio
          POSTGRES_PASSWORD: qurio-test
          POSTGRES_DB: qurio
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U qurio"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    env:
      POSTGRES_DSN: postgres://qurio:qurio-test@127.0.0.1:5432/qurio?sslmode=disable
      QURIO_INTEGRATION_DSN: postgres://qurio:qurio-test@127.0.0.1:5432/qurio?sslmode=disable
      QURIO_TEST_POSTGRES_DSN: postgres://qurio:qurio-test@127.0.0.1:5432/qurio?sslmode=disable
      BOOTSTRAP_ADMIN: admin@example.test
      BOOTSTRAP_ADMIN_PASSWORD: CI-only-password-42!
      ENCRYPTION_KEY: YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4eXoxMjM0NTY=
    steps:
      - uses: actions/checkout@v7
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v7
        with:
          node-version: 26
          cache: npm
          cache-dependency-path: web/package-lock.json
      - run: npm ci --prefix web
      - run: npm run lint --prefix web
      - run: npm run typecheck --prefix web
      - run: npm test --prefix web -- --run
      - run: npm run build --prefix web
      - run: npm audit --prefix web --omit=dev --audit-level=high
      - name: Install Playwright browser
        working-directory: web
        run: npx playwright install --with-deps chromium
      - run: npm run test:e2e --prefix web
      - name: Verify installation into a completely empty database
        run: go test -tags=integration ./cmd/qurio -run '^TestIntegrationFreshInstallDatabase$' -count=1
      - name: Bootstrap and verify integration database migrations
        run: go test -tags=integration ./cmd/qurio -run '^TestIntegrationDatabaseMigrations$' -count=1
      # Integration packages share the single disposable service database.
      # Serialize packages so one package cannot observe another package's
      # migration/bootstrap transaction half-way through initialization.
      - run: go test -race -p=1 -tags=integration ./...
      - run: go vet -tags=integration ./...
      - name: Go vulnerability scan
        run: |
          go install golang.org/x/vuln/cmd/govulncheck@v1.6.0
          govulncheck ./...
      - name: Go security scan
        run: |
          go install github.com/securego/gosec/v2/cmd/gosec@v2.28.0
          gosec -quiet ./...
