func oracleReadOnlyViolations(sql string) ([]string, bool) {
	tokens, hasDatabaseLink, valid := scanOraclePolicy(sql)
	var reasons reasonSet
	if hasDatabaseLink {
		reasons.add("Oracle database link(@) 참조는 허용되지 않습니다.")
	}
	if !valid {
		return reasons.list(), true
	}
	for index, token := range tokens {
		if token.kind != oraclePolicyLeftParen || index == 0 || tokens[index-1].kind != oraclePolicyWord {
			continue
		}
		nameToken := tokens[index-1]
		name := strings.ToUpper(nameToken.value)
		// Quoted identifiers carry no recorded source position, so they stay on
		// the blocking path exactly as before.
		if !nameToken.quoted && !callAdjacent(sql, nameToken, token) {
			continue
		}
		if !nameToken.quoted {
			if _, grammar := oracleParenthesisKeywords[name]; grammar {
				continue
			}
		}
		qualified := index >= 2 && tokens[index-2].kind == oraclePolicyDot
		_, intrinsic := oraclePureFunctions[name]
		if nameToken.quoted || qualified || !intrinsic {
			display := boundedToken(nameToken.value, 96)
			reasons.add(fmt.Sprintf("Oracle SELECT의 비허용 함수 호출 %s()이 포함되어 있습니다.", display))
		}
	}
	for _, token := range tokens {
		if token.kind != oraclePolicyWord {
			continue
		}
		switch strings.ToUpper(token.value) {
		case "NEXTVAL", "CURRVAL":
			reasons.add("Oracle sequence 의사컬럼 NEXTVAL/CURRVAL은 허용되지 않습니다.")
		}
	}
	return reasons.list(), false
}

func boundedToken(value string, maximum int) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "<quoted>"
	}
	if len(value) > maximum {
		value = value[:maximum]
	}
	return value
}

// directly-after-WITH shortcut.
func TestAnalyzeDialectAllowsPostgresLaterCTEColumnLists(t *testing.T) {
	t.Parallel()
	queries := []string{
		`WITH a (x) AS (SELECT 1), b (y) AS (SELECT 2) SELECT * FROM a, b`,
		`WITH RECURSIVE t (n) AS (SELECT 1), u (m) AS (SELECT 2) SELECT * FROM t, u`,
		`WITH a (x) AS (SELECT 1), b (y) AS (SELECT 2), c (z) AS (SELECT 3) SELECT * FROM a, b, c`,
		`WITH a AS (SELECT 1), b (y) AS (SELECT 2) SELECT * FROM a, b`,
		`WITH a (x) AS (SELECT upper(n) FROM public.events), b (y) AS (SELECT 2) SELECT * FROM a, b`,
	}
	for _, query := range queries {
		analysis := AnalyzeDialect(query, "postgres")
		if !analysis.ReadOnly || analysis.Risk == RiskBlocked {
			t.Fatalf("PostgreSQL later CTE column list was rejected for %q: %#v", query, analysis)
		}
	}
}

// The same search must not exempt a call that only looks like a later query
// name. Reaching SELECT or VALUES at the list depth proves the comma separated a
// projection or a row list rather than a WITH list, so the call stays subject to
// the allowlist. The last case puts a real call inside the first CTE and a
// genuine query name after it. The last two put a WITH list inside a subquery
// and the call outside it: the search skips tokens at other depths rather than
// stepping over the group, so it crosses that inner list, and a memo keyed on the
// cursor alone — rather than on the cursor and the list depth together — hands
// the call the inner list's answer and exempts it.
func TestAnalyzeDialectLaterCTESearchDoesNotExemptFunctionCalls(t *testing.T) {
	t.Parallel()
	for _, query := range []string{
		`SELECT upper (x) AS a, side_effect_fn (y) AS b FROM public.events`,
		`SELECT 1 AS a, custom_reporting_fn (2) AS b`,
		`SELECT * FROM (VALUES (1), custom_reporting_fn (2) AS t) v`,
		`WITH a (x) AS (SELECT 1, side_effect_fn (2) AS q) SELECT * FROM a`,
		`WITH a (x, y) AS (SELECT 1, side_effect_fn (2) AS q), b (z) AS (SELECT 3) SELECT * FROM a, b`,
		`SELECT * FROM (WITH p (x) AS (SELECT 1), q (y) AS (SELECT 2) SELECT * FROM p, q) sub, side_effect_fn (3) AS z`,
		`SELECT * FROM (WITH p (x) AS (SELECT 1), q (y) AS (SELECT 2) SELECT 1) sub, custom_reporting_fn (3) AS z`,
	} {
		analysis := AnalyzeDialect(query, "postgres")
		if analysis.ReadOnly || analysis.Risk != RiskBlocked {
			t.Fatalf("PostgreSQL call after a comma was exempted for %q: %#v", query, analysis)
		}
	}
}

// The CTE column list check runs once per call that is followed by `AS`, and its
// backward WITH search used to re-walk the token stream to index 0 at every such
// site. A list of aliased calls — the shape of any ordinary projection — then cost
// quadratic time on the same endpoint and with the same reach as the chained call
// shape above: 4000/8000/16000 terms measured 112 ms/446 ms/1.76 s before the
// memo, exactly four times the cost for twice the bytes. The budget is
// deliberately loose; the quadratic scan misses it by orders of magnitude, not by
// a few percent. Kept serial so a loaded -race run of the parallel tests above
// cannot skew the measurement.
func TestAnalyzeDialectScalesLinearlyOverAliasedPostgresCalls(t *testing.T) {
	const terms = 16000
	var builder strings.Builder
	builder.WriteString("SELECT ")
	for index := 0; index < terms; index++ {
		if index > 0 {
			builder.WriteString(", ")
		}
		fmt.Fprintf(&builder, "upper (x) AS a%d", index)
	}
	builder.WriteString(" FROM public.events")
	query := builder.String()

	start := time.Now()
	analysis := AnalyzeDialect(query, "postgres")
	elapsed := time.Since(start)

	if !analysis.ReadOnly || analysis.Risk == RiskBlocked {
		t.Fatalf("aliased intrinsic calls were rejected: %#v", analysis)
	}
	if elapsed > 500*time.Millisecond {
		t.Fatalf("AnalyzeDialect took %s for a %d byte query; the CTE column list check is re-scanning the token stream per call site", elapsed, len(query))
	}
}

// The reasons a blocked statement carries quote identifiers lifted out of the
// query, so their cardinality is bounded only by the query length. Deduplicating
// each new reason against every reason already collected is quadratic in the
// number of *distinct* reasons, and the three cases below are the reason sites
// that a caller can drive to that cardinality: PostgreSQL function names, Oracle
// function names, and PostgreSQL cast target types. validateSQL hands an
// authenticated principal up to 1<<20 bytes with no database privilege at all.
const distinctReasonTerms = 64000

func TestAnalyzeDialectScalesLinearlyOverDistinctPostgresFunctionReasons(t *testing.T) {
	var builder strings.Builder
	builder.WriteString("SELECT ")
	for index := 0; index < distinctReasonTerms; index++ {
		if index > 0 {
			builder.WriteString(", ")
		}
		fmt.Fprintf(&builder, "f%d(x)", index)
	}
	builder.WriteString(" FROM public.events")
	query := builder.String()

	start := time.Now()
	analysis := AnalyzeDialect(query, "postgres")
	elapsed := time.Since(start)

	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
		t.Fatalf("distinct stored function calls were accepted: ReadOnly=%t Risk=%s", analysis.ReadOnly, analysis.Risk)
	}
	if elapsed > time.Second {
		t.Fatalf("AnalyzeDialect took %s for a %d byte postgres query producing %d distinct reasons; reason accumulation is comparing each new reason against every reason already collected", elapsed, len(query), distinctReasonTerms)
	}
}

