// Order and deduplication of the reason list are the observable contract the
// dialect gates and the merge below AnalyzeDialect share: the base statement
// reasons come first in scan order, the dialect reasons follow in the order the
// gate found them, and nothing repeats. This pins the behaviour that the
// membership index must not change.
func TestAnalyzeDialectDeduplicatesAndOrdersViolationReasons(t *testing.T) {
	t.Parallel()
	analysis := AnalyzeDialect(`SELECT pg_sleep(1), side_effect_fn(x), pg_sleep(2), side_effect_fn(y), other_fn(z) FROM public.events WHERE x COLLATE "C" > 'a' AND y TABLESAMPLE`, "postgres")
	if analysis.ReadOnly || analysis.Risk != RiskBlocked {
		t.Fatalf("statement was accepted: %#v", analysis)
	}
	want := []string{
		"관리자 확인이 필요한 함수 PG_SLEEP가 포함되어 있습니다.",
		"PostgreSQL의 명시적 COLLATE 절은 허용되지 않습니다.",
		"PostgreSQL TABLESAMPLE access method 호출은 허용되지 않습니다.",
		"PostgreSQL SELECT의 비허용 함수 호출 pg_sleep()이 포함되어 있습니다.",
		"PostgreSQL SELECT의 비허용 함수 호출 side_effect_fn()이 포함되어 있습니다.",
		"PostgreSQL SELECT의 비허용 함수 호출 other_fn()이 포함되어 있습니다.",
	}
	if len(analysis.Reasons) != len(want) {
		t.Fatalf("reasons = %#v, want %d entries", analysis.Reasons, len(want))
	}
	for index, reason := range want {
		if analysis.Reasons[index] != reason {
			t.Fatalf("reasons[%d] = %q, want %q (full list %#v)", index, analysis.Reasons[index], reason, analysis.Reasons)
		}
	}
}

