func (a *API) validateSQL(w http.ResponseWriter, r *http.Request) {
	principal, ok := a.principalFor(w, r)
	if !ok {
		return
	}
	var request sqlRequest
	if !decodeJSON(w, r, &request) {
		return
	}
	if len(request.SQL) == 0 || len(request.SQL) > 1<<20 {
		httpapi.WriteAPIError(w, r, http.StatusBadRequest, "invalid_sql", "검증할 SQL을 입력해 주세요.")
		return
	}
	analysis := sqlsafe.AnalyzeDialect(request.SQL, request.Dialect)
	status := http.StatusOK
	if !analysis.ReadOnly {
		status = http.StatusUnprocessableEntity
	}
	response := map[string]any{"valid": analysis.ReadOnly, "analysis": analysis}
	if analysis.ReadOnly && strings.TrimSpace(request.DatabaseID) != "" {
		request.DatabaseID = strings.TrimSpace(request.DatabaseID)
		if !a.requireDatabaseAccess(w, r, principal, request.DatabaseID) {
			httpapi.WriteAPIError(w, r, http.StatusForbidden, "database_scope_denied", "이 데이터베이스에 접근할 수 없습니다.")
			return
		}
		validation, err := a.ValidateSQLForAgent(r.Context(), request.DatabaseID, request.SQL)
		response["analysis"] = validation.Analysis
		response["databaseValidation"] = validation
		response["valid"] = err == nil && validation.Valid
		if err != nil {
			status = http.StatusUnprocessableEntity
		}
	}
	writeJSON(w, status, response)
}

func (a *API) executeSQL(w http.ResponseWriter, r *http.Request) {
	principal, ok := a.principalFor(w, r)
