	if !decodeJSON(w, r, &request) {
		return
	}
	result, runID, err := a.execute(r.Context(), principal, request, httpapi.RequestID(r))
	if err != nil {
		a.writeExecutionError(w, r, err)
		return
	}
	if _, err := a.authorizeSQLPublication(r.Context(), principal, request.DatabaseID); err != nil {
		a.writeExecutionError(w, r, err)
		return
	}
	data, err := json.Marshal(map[string]any{"runId": runID, "result": result})
	if err != nil {
		httpapi.WriteAPIError(w, r, http.StatusInternalServerError, "result_encoding_failed", "SQL 실행 결과를 인코딩하지 못했습니다.")
		return
	}
	data = append(data, '\n')
	header := make(http.Header)
	header.Set("Content-Type", "application/json; charset=utf-8")
	header.Set("Cache-Control", "no-store")
	a.publishProtectedReader(w, r, principal, http.StatusOK, header, bytes.NewReader(data),
		a.resourcePublicationAuthorization("sql.execute", "DATABASE", strings.TrimSpace(request.DatabaseID), false))
}

