func (a *API) createSQLApproval(w http.ResponseWriter, r *http.Request) {
	principal, ok := a.principalFor(w, r)
	if !ok {
		return
	}
	var request sqlApprovalRequest
	if !decodeJSON(w, r, &request) {
		return
	}
	request.DatabaseID = strings.TrimSpace(request.DatabaseID)
	request.SQL = strings.TrimSpace(request.SQL)
	request.Reason = strings.TrimSpace(request.Reason)
	if !validDatabaseID(request.DatabaseID) || request.SQL == "" || len(request.SQL) > 1<<20 || request.Reason == "" || len(request.Reason) > 4000 {
		httpapi.WriteAPIError(w, r, http.StatusBadRequest, "invalid_approval_request", "데이터베이스, SQL, 승인 사유를 확인해 주세요.")
		return
	}
	if !a.requireDatabaseAccess(w, r, principal, request.DatabaseID) {
		httpapi.WriteAPIError(w, r, http.StatusForbidden, "database_scope_denied", "이 데이터베이스에 접근할 수 없습니다.")
		return
	}
	analysis, err := sqlsafe.RequireReadOnly(request.SQL)
	if err != nil {
		httpapi.WriteAPIError(w, r, http.StatusUnprocessableEntity, "unsafe_sql", "단일 읽기 전용 SQL만 승인 요청할 수 있습니다.")
		return
	}
	validation, err := a.ValidateSQLForAgent(r.Context(), request.DatabaseID, request.SQL)
	if err != nil || !validation.Valid {
		httpapi.WriteAPIError(w, r, http.StatusUnprocessableEntity, "sql_validation_failed", "대상 데이터베이스 검증을 통과한 SQL만 승인 요청할 수 있습니다.")
		return
	}
	decision, err := a.RequestSQLApprovalForAgent(r.Context(), request.DatabaseID, request.SQL, string(analysis.Risk), request.Reason)
	if err != nil {
		a.logger.Error("SQL approval request failed", "request_id", httpapi.RequestID(r), "error", err)
		httpapi.WriteAPIError(w, r, http.StatusBadGateway, "approval_request_failed", "SQL 승인 요청을 만들지 못했습니다.")
		return
	}
	status := http.StatusOK
	if decision.ReviewRequired {
		status = http.StatusAccepted
	}
	writeJSON(w, status, decision)
}

