func postgresReadOnlyViolations(sql string) ([]string, bool) {
	tokens, _, valid := scanOraclePolicy(sql)
	if !valid {
		return nil, true
	}
	var reasons reasonSet
	for _, token := range tokens {
		if token.kind != oraclePolicyWord || token.quoted {
			continue
		}
		switch strings.ToUpper(token.value) {
		case "TABLESAMPLE":
			reasons.add("PostgreSQL TABLESAMPLE access method 호출은 허용되지 않습니다.")
		case "COLLATE":
			// A collation name is resolved by the server and can name an ICU or
			// extension-provided object. Qurio cannot prove its implementation
			// from text alone, so explicit COLLATE clauses fail closed. Implicit
			// column collations are checked against catalog provenance by dbexec.
			reasons.add("PostgreSQL의 명시적 COLLATE 절은 허용되지 않습니다.")
		}
	}
	for _, token := range tokens {
		if token.kind != postgresPolicyString {
			continue
		}
		if reason := postgresTypeLiteralViolation(sql, int(token.start)); reason != "" {
			reasons.add(reason)
		}
	}
	// One token index serves every call site in this statement; it is built on
	// first use so queries without a candidate call pay nothing.
	tokenIndex := postgresTokenIndex{tokens: tokens}
	for index, token := range tokens {
		if token.kind != oraclePolicyLeftParen || index == 0 || tokens[index-1].kind != oraclePolicyWord {
			continue
		}
		nameToken := tokens[index-1]
		name := strings.ToUpper(nameToken.value)
		if postgresAliasColumnList(&tokenIndex, index-1) {
			continue
		}
		// Quoted identifiers carry no recorded source position, so they stay on
		// the blocking path exactly as before.
		if !nameToken.quoted && !callAdjacent(sql, nameToken, token) {
			continue
		}
		if !nameToken.quoted {
			if _, grammar := postgresParenthesisKeywords[name]; grammar {
				continue
			}
		}
		qualified := index >= 2 && tokens[index-2].kind == oraclePolicyDot
		_, intrinsic := postgresPureFunctions[name]
		if nameToken.quoted || qualified || !intrinsic {
			display := boundedToken(nameToken.value, 96)
			reasons.add(fmt.Sprintf("PostgreSQL SELECT의 비허용 함수 호출 %s()이 포함되어 있습니다.", display))
		}
	}
	for index, token := range tokens {
		if token.kind == postgresPolicyCast {
			if reason := postgresCastTypeViolation(tokens, index+1); reason != "" {
				reasons.add(reason)
			}
			continue
		}
		if token.kind != oraclePolicyWord || token.quoted || !strings.EqualFold(token.value, "CAST") || index+1 >= len(tokens) || tokens[index+1].kind != oraclePolicyLeftParen {
			continue
		}
		depth := 0
		for cursor := index + 1; cursor < len(tokens); cursor++ {
			switch tokens[cursor].kind {
			case oraclePolicyLeftParen:
				depth++
			case oraclePolicyRightParen:
				depth--
				if depth == 0 {
					cursor = len(tokens)
				}
			case oraclePolicyWord:
				if depth == 1 && !tokens[cursor].quoted && strings.EqualFold(tokens[cursor].value, "AS") {
					if reason := postgresCastTypeViolation(tokens, cursor+1); reason != "" {
						reasons.add(reason)
					}
					cursor = len(tokens)
				}
			}
		}
	}
	return reasons.list(), false
}

