func TestAnalyzeReadOnly(t *testing.T) {
	t.Parallel()
	for _, query := range []string{
		"select id, name from customers",
		"WITH recent AS (SELECT * FROM orders) SELECT * FROM recent;",
		"-- note\nSELECT 'drop table users' AS harmless",
		`SELECT "delete" FROM audit_log`,
	} {
		analysis := Analyze(query)
		if !analysis.ReadOnly || analysis.Risk == RiskBlocked {
			t.Fatalf("expected read-only for %q: %#v", query, analysis)
		}
	}
}

func TestAnalyzeBlocksDangerousSQL(t *testing.T) {
	t.Parallel()
	tests := []string{
		"DELETE FROM users",
		"SELECT 1; DROP TABLE users",
		"WITH changed AS (UPDATE users SET name='x' RETURNING *) SELECT * FROM changed",
		"EXPLAIN ANALYZE UPDATE users SET name='x'",
		"DO $$ BEGIN DELETE FROM users; END $$",
		"SELECT 'unterminated",
	}
	for _, query := range tests {
		analysis := Analyze(query)
		if analysis.ReadOnly || analysis.Risk != RiskBlocked {
			t.Fatalf("expected blocked for %q: %#v", query, analysis)
		}
	}
}

