func TestWriteExecutionErrorReportsDatabaseProfilePolicy(t *testing.T) {
	tests := []struct {
		name       string
		err        error
		wantStatus int
		wantCode   string
	}{
		{name: "row limit", err: errors.Join(dbexec.ErrRowLimitExceeded, errors.New("details")), wantStatus: http.StatusUnprocessableEntity, wantCode: "row_limit_exceeded"},
		{name: "schema", err: errors.Join(dbexec.ErrSchemaNotAllowed, errors.New("details")), wantStatus: http.StatusForbidden, wantCode: "schema_not_allowed"},
		{name: "Oracle dialect safety", err: errors.Join(dbexec.ErrUnsafeStatement, errors.New("details")), wantStatus: http.StatusUnprocessableEntity, wantCode: "unsafe_sql"},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(http.MethodPost, "/sql/execute", nil)
			(&API{}).writeExecutionError(recorder, request, test.err)
			if recorder.Code != test.wantStatus {
				t.Fatalf("status = %d, want %d", recorder.Code, test.wantStatus)
			}
			var body map[string]any
			if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
				t.Fatal(err)
			}
			if body["code"] != test.wantCode {
				t.Fatalf("body = %#v", body)
			}
			if got := executionErrorCode(test.err); got != test.wantCode {
				t.Fatalf("durable error code = %q, want %q", got, test.wantCode)
			}
		})
	}
}
