	firstTargetSchema, firstTargetSchemaOK := args[1].(sql.NamedArg)
	secondTargetTable, secondTargetTableOK := args[4].(sql.NamedArg)
	if !strings.Contains(foreignKeys, "UPPER(pkc.table_name)=:target_table_1") || len(args) != 5 || !firstTargetSchemaOK || firstTargetSchema.Name != "target_schema_0" || firstTargetSchema.Value != "ANALYTICS" || !secondTargetTableOK || secondTargetTable.Name != "target_table_1" || secondTargetTable.Value != "CUSTOMERS" {
		t.Fatalf("Oracle targeted FK bindings mismatch: query=%s args=%v", foreignKeys, args)
	}
}

func TestNormalizeSchemaTargetsRejectsUnboundedOrMalformedHints(t *testing.T) {
	valid, err := normalizeSchemaTargets([]SchemaTarget{{Schema: " public ", Table: " sales "}, {Schema: "PUBLIC", Table: "SALES"}})
	if err != nil || len(valid) != 1 || valid[0].Schema != "public" || valid[0].Table != "sales" {
		t.Fatalf("normalized targets = %#v, %v", valid, err)
	}
	if _, err := normalizeSchemaTargets(nil); err == nil {
		t.Fatal("empty target list was accepted")
	}
	if _, err := normalizeSchemaTargets([]SchemaTarget{{Table: strings.Repeat("x", 129)}}); err == nil {
		t.Fatal("oversized target was accepted")
	}
	tooMany := make([]SchemaTarget, maxSchemaHints+1)
	for index := range tooMany {
		tooMany[index].Table = fmt.Sprintf("table_%d", index)
	}
	if _, err := normalizeSchemaTargets(tooMany); err == nil {
		t.Fatal("unbounded target list was accepted")
	}
}

func TestDataSourcesEscapeCredentials(t *testing.T) {
	t.Setenv("PGOPTIONS", "-c search_path=attacker")
	t.Setenv("PGAPPNAME", "ambient-application")
	postgres := Connection{ID: "p", Name: "Postgres", Dialect: Postgres, Host: "db.internal", Port: 5432, Username: "user@team", Password: "p/a:ss?word", Database: "warehouse", Timeout: time.Second}
	driver, dsn, err := dataSource(postgres)
	if err != nil || driver != "pgx" {
		t.Fatalf("postgres source: %s %v", driver, err)
	}
	if strings.Contains(dsn, "p/a:ss?word") || !strings.Contains(dsn, "postgres://") {
		t.Fatalf("unsafe postgres DSN: %s", dsn)
	}
	parsedPostgres, parseErr := url.Parse(dsn)
	if parseErr != nil || parsedPostgres.Query().Has("options") || parsedPostgres.Query().Get("application_name") == "ambient-application" {
		t.Fatalf("ambient Postgres configuration affected DSN: %s err=%v", dsn, parseErr)
	}
	t.Setenv("USER", "ambient-oracle-user")
	oracle := Connection{ID: "o", Name: "Oracle", Dialect: Oracle, Host: "ora.internal", Port: 1521, Username: "scott", Password: "tiger/@?", Database: "FREEPDB1", Timeout: time.Second}
	driver, dsn, err = dataSource(oracle)
	if err != nil || driver != "oracle" {
		t.Fatalf("oracle source: %s %v", driver, err)
	}
	if strings.Contains(dsn, "tiger/@?") || !strings.HasPrefix(dsn, "oracle://") {
		t.Fatalf("unsafe oracle DSN: %s", dsn)
	}
	parsedOracle, parseErr := url.Parse(dsn)
	if parseErr != nil || parsedOracle.Query().Get("OS USER") != "qurio" || strings.Contains(dsn, "ambient-oracle-user") {
		t.Fatalf("Oracle AUTH_SID is not deterministic: %s err=%v", dsn, parseErr)
	}
}

func TestBoundedQueryPreservesPageCeiling(t *testing.T) {
	query, err := boundedQuery("SELECT * FROM sales", Postgres, 3, 25)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(query, "LIMIT 76") {
		t.Fatalf("query = %s", query)
	}
	query, err = boundedQuery("SELECT * FROM sales", Oracle, 2, 100)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(query, "ROWNUM <= 201") {
		t.Fatalf("query = %s", query)
	}
	if _, err := boundedQuery("DELETE FROM sales", Oracle, 1, 10); err == nil {
		t.Fatal("mutation was accepted")
	}
	query, err = boundedQuery("SELECT * FROM sales", Postgres, 1, 100_000)
	if err != nil || !strings.Contains(query, "LIMIT 100001") {
		t.Fatalf("100K boundary query = %s, %v", query, err)
	}
	query, err = boundedQuery("SELECT * FROM sales", Postgres, 11, 100_000)
	if err != nil || !strings.Contains(query, "LIMIT 1100001") {
		t.Fatalf("maximum offset boundary query = %s, %v", query, err)
	}
	for _, page := range []int{12, int(^uint(0) >> 1)} {
		if _, err := boundedQuery("SELECT * FROM sales", Postgres, page, 100_000); err == nil {
			t.Fatalf("overflowing or excessive page %d was accepted", page)
		}
	}
}

func TestManagerRejectsOracleRemoteAndStoredCodeBeforeDriver(t *testing.T) {
	t.Parallel()
	manager := New(nil)
	manager.entries["oracle"] = &entry{config: Connection{
		ID: "oracle", Name: "Oracle", Dialect: Oracle, Host: "127.0.0.1", Port: 1521,
		Username: "reader", Password: "password", Database: "service", Timeout: time.Second,
	}}

	for _, statement := range []string{
		`SELECT * FROM reporting.sales@remote_link`,
		`SELECT side_effect_fn() FROM dual`,
	} {
		if _, err := manager.Execute(context.Background(), "oracle", statement, 1, 10); !errors.Is(err, ErrUnsafeStatement) {
			t.Fatalf("Execute policy error for %q = %v", statement, err)
		}
		validation, err := manager.Validate(context.Background(), "oracle", statement)
		var rejected *ValidationError
		if !errors.As(err, &rejected) || !errors.Is(err, ErrUnsafeStatement) || validation.Valid || validation.Diagnostic == nil || validation.Diagnostic.Code != "unsafe_sql" {
			t.Fatalf("Validate did not fail closed for %q: validation=%+v error=%T %v", statement, validation, err, err)
		}
	}
}

